import { useMemo } from 'react';
import { useIntl } from 'react-intl';

import type { TocGroup } from 'components/TableOfContents';
import { useAssetHost } from 'config/api';
import { COUNTRIES } from 'pages/pillars/ValueCreation/VolumePages/tabs/Global/constants/countries';
import { PageInfo } from 'pages/types';

import {
  pageSections,
  SUMMARY_COUNTRY_SECTION_MAP,
  SUMMARY_MUST_WIN_COUNTRIES,
  SUMMARY_TOC_MESSAGE_IDS,
} from '../../constants';

const getPageIndex = (
  getPageByName: (name: string) => PageInfo | undefined,
  slideId: string,
): number => getPageByName(slideId)?.index ?? 0;

export const useSummaryTocGroups = (
  getPageByName: (name: string) => PageInfo | undefined,
): TocGroup[] => {
  const { formatMessage } = useIntl();
  const assetHost = useAssetHost();

  return useMemo(() => {
    const page = (slideId: string) => getPageIndex(getPageByName, slideId);
    const t = (id: string, values?: Record<string, string>) =>
      formatMessage({ id }, values);

    return [
      {
        layout: 'stacked',
        items: [
          {
            title: t(SUMMARY_TOC_MESSAGE_IDS.globalResults),
            page: page(pageSections.globalResultsCover),
            slideId: pageSections.globalResultsCover,
            subItems: [
              {
                label: t(SUMMARY_TOC_MESSAGE_IDS.totalGlobalCountryBreakdown),
                page: page(pageSections.globalVolume),
                slideId: pageSections.globalVolume,
              },
              {
                label: t(SUMMARY_TOC_MESSAGE_IDS.ytdTopBottomBrands),
                page: page(pageSections.topBrandsYtd),
                slideId: pageSections.topBrandsYtd,
              },
              {
                label: t(SUMMARY_TOC_MESSAGE_IDS.mtdTopBottomBrands),
                page: page(pageSections.topBrandsMtd),
                slideId: pageSections.topBrandsMtd,
              },
            ],
          },
          {
            title: t(SUMMARY_TOC_MESSAGE_IDS.globalMoves),
            page: page(pageSections.globalMovesCover),
            slideId: pageSections.globalMovesCover,
            subItems: [
              {
                label: t(SUMMARY_TOC_MESSAGE_IDS.coronaCountryBreakdown),
                page: page(pageSections.coronaVolumeCountriesBreakdown),
                slideId: pageSections.coronaVolumeCountriesBreakdown,
              },
              {
                label: t(SUMMARY_TOC_MESSAGE_IDS.nonAlcBeerCountryBreakdown),
                page: page(pageSections.nonAlcBeerVolumeCountriesBreakdown),
                slideId: pageSections.nonAlcBeerVolumeCountriesBreakdown,
              },
              {
                label: t(SUMMARY_TOC_MESSAGE_IDS.beyondBeerCountryBreakdown),
                page: page(pageSections.beyondBeerVolumeCountriesBreakdown),
                slideId: pageSections.beyondBeerVolumeCountriesBreakdown,
              },
            ],
          },
          {
            title: t(SUMMARY_TOC_MESSAGE_IDS.mustWinMarkets),
            page: page(pageSections.mustWinMarketsCover),
            slideId: pageSections.mustWinMarketsCover,
            subItems: SUMMARY_MUST_WIN_COUNTRIES.map((countryCode) => {
              const config = COUNTRIES[countryCode];
              const slideId = SUMMARY_COUNTRY_SECTION_MAP[countryCode];
              const countryName =
                countryCode === 'ZAF'
                  ? t(SUMMARY_TOC_MESSAGE_IDS.countryShortSouthAfrica)
                  : config.countryName;

              return {
                label: t(SUMMARY_TOC_MESSAGE_IDS.countryTotalResults, {
                  countryName,
                }),
                page: page(slideId),
                slideId,
                countryCode,
                countryName,
                countryImageUrl: `${assetHost}/countries/rounded_flags/${countryCode}.png`,
              };
            }),
          },
        ],
      },
    ];
  }, [assetHost, formatMessage, getPageByName]);
};
